/** Neutral-only native integration checks, excluded from the release source set. */
final class MobileParityChecks {
    private static final String TAG="DARTParityQA";
    static void run(Activity activity,ImageLoader images){new Handler(Looper.getMainLooper()).postDelayed(()->{
        try{if(!activity.getIntent().getBooleanExtra("qaFixtures",false))throw new IllegalStateException("Neutral fixtures required");
            String mode=activity.getIntent().getStringExtra("qaParityMode");if(mode==null)mode="state";
            if(mode.startsWith("reliability-")){MobileMediaReliabilityChecks.run(activity,images,mode);return;}
            if(mode.equals("following-fairness")){MobileFollowingReliabilityChecks.run(activity,images);return;}
            Store store=(Store)field(activity,"store");
            if(mode.equals("import")){String json;try(InputStream in=new FileInputStream(new File(activity.getExternalFilesDir(null),"dart-qa-profile.json"))){json=new String(in.readAllBytes(),StandardCharsets.UTF_8);}JSONObject document=ProfileTransfer.parse(json);method(activity,"showImportPreview",JSONObject.class).invoke(activity,document);Log.i(TAG,"IMPORT PREVIEW opened counts="+ProfileTransfer.counts(document));}
            else if(mode.equals("verify")){JSONObject exported=ProfileTransfer.export(store.export());boolean like=has(exported.optJSONArray("likes"),"danbooru:9000999"),bookmark=has(exported.optJSONArray("bookmarks"),"danbooru:9000998"),follow=store.following("artcatalog_test_artist");boolean viewed=false;JSONArray seen=exported.optJSONArray("viewedIdentities");if(seen!=null)for(int i=0;i<seen.length();i++)if(seen.optString(i).equals("key:danbooru:9000997"))viewed=true;
                File file=new File(activity.getExternalFilesDir(null),"dart-qa-export.json");try(FileOutputStream out=new FileOutputStream(file)){out.write(exported.toString(2).getBytes(StandardCharsets.UTF_8));}
                File[] backups=activity.getFilesDir().listFiles((directory,name)->name.startsWith("catalog-before-import-"));JSONArray history=exported.optJSONArray("history");List<Post> nativeHistory=store.history();boolean historyOrder=history!=null&&history.length()==nativeHistory.size();if(historyOrder)for(int i=0;i<history.length();i++)if(!nativeHistory.get(i).key().equals(history.optJSONObject(i).optString("key")))historyOrder=false;
                Log.i(TAG,"PERSISTENCE like="+like+" bookmark="+bookmark+" follow="+follow+" viewed="+viewed+" historyOrder="+historyOrder+" backups="+(backups==null?0:backups.length)+" counts="+ProfileTransfer.counts(exported));}
            else if(mode.equals("language")){method(activity,"languageSettings").invoke(activity);Log.i(TAG,"LANGUAGE opened current="+store.prefs.getString("language","en"));}
            else if(mode.equals("transfer-settings")){method(activity,"profileTransferSettings").invoke(activity);Log.i(TAG,"TRANSFER SETTINGS opened");}
            else if(mode.equals("live-prefix"))livePrefix(activity,store);
            else if(mode.equals("following")){method(activity,"selectNav",int.class).invoke(activity,2);Log.i(TAG,"FOLLOWING opened");}
            else if(mode.equals("following-slow"))followingSlow(activity,store);
            else if(mode.equals("cache-renewal"))cacheRenewal(activity,images);
            else if(mode.equals("import-failure"))importFailure(activity,store);
            else if(mode.equals("pagination"))pagination(activity,store);
            else if(mode.equals("warm-followed"))warmFollowed(activity,store);
            else if(mode.equals("failed-preview"))failedPreview(activity,store,images);
            else if(mode.equals("video")||mode.equals("video-late"))video(activity);
            else{Log.i(TAG,"STATE language="+store.prefs.getString("language","en")+" counts="+ProfileTransfer.counts(ProfileTransfer.export(store.export()))+" client="+field(activity,"client").getClass().getSimpleName());}
        }catch(Exception error){Log.e(TAG,"FAILED",error);}
    },1800);}
    private static void livePrefix(Activity activity,Store store)throws Exception{
        Object source=((Object[])field(activity,"screens"))[0];List<Post> before=new ArrayList<>((List<Post>)field(source,"posts"));if(before.size()<2)throw new IllegalStateException("Fixture feed has not loaded");
        Post first=before.get(0),second=before.get(1);store.prefs.edit().putBoolean("hideViewedAndSaved",true).commit();
        Class<?> gallery=Class.forName("com.artcatalog.mobile.MainActivity$Gallery");method(activity,"openArtwork",Post.class,gallery).invoke(activity,first,null);store.like(first);store.toggle(second);method(activity,"goBack").invoke(activity);
        new Handler(Looper.getMainLooper()).postDelayed(()->{try{List<Post> after=(List<Post>)field(source,"posts");boolean retained=after.stream().anyMatch(p->p.key().equals(first.key()))&&after.stream().anyMatch(p->p.key().equals(second.key()));boolean saved=store.liked(first)&&store.saved(second);Log.i(TAG,"LIVE PREFIX retained="+retained+" like/bookmark="+saved+" before="+before.size()+" after="+after.size());}catch(Exception error){Log.e(TAG,"LIVE PREFIX failed",error);}},1200);
    }
    private static void video(Activity activity)throws Exception{
        int resource=activity.getResources().getIdentifier("dart_qa_video","raw",activity.getPackageName());byte[] bytes;try(InputStream in=activity.getResources().openRawResource(resource)){bytes=in.readAllBytes();}
        ServerSocket server=new ServerSocket(0,8,InetAddress.getByName("127.0.0.1"));Thread serving=new Thread(()->{try{while(!server.isClosed()){Socket socket=server.accept();Thread request=new Thread(()->{try(Socket client=socket){BufferedReader input=new BufferedReader(new InputStreamReader(client.getInputStream(),StandardCharsets.US_ASCII));String line=input.readLine();String header;int start=0;while(!(header=input.readLine()).isEmpty()){if(header.toLowerCase(Locale.ROOT).startsWith("range: bytes=")){String value=header.substring(header.indexOf('=')+1).split("-",2)[0];if(!value.isEmpty())start=Integer.parseInt(value);}}start=Math.min(start,bytes.length-1);OutputStream out=client.getOutputStream();String response="HTTP/1.1 206 Partial Content\r\nContent-Type: video/mp4\r\nAccept-Ranges: bytes\r\nContent-Range: bytes "+start+"-"+(bytes.length-1)+"/"+bytes.length+"\r\nContent-Length: "+(bytes.length-start)+"\r\nConnection: close\r\n\r\n";out.write(response.getBytes(StandardCharsets.US_ASCII));out.write(bytes,start,bytes.length-start);out.flush();Log.i(TAG,"VIDEO loopback request "+line);}catch(Exception e){Log.e(TAG,"VIDEO fixture",e);}},"DART-QA-video-request");request.setDaemon(true);request.start();}}catch(Exception ignored){}},"DART-QA-video-server");serving.setDaemon(true);serving.start();
        List<Post> fixtures=(List<Post>)field(field(activity,"client"),"fixtures");Post v=Post.fromJson(fixtures.get(6).toJson());v.id="9990001";v.title="Neutral motion fixture";v.image="http://127.0.0.1:"+server.getLocalPort()+"/neutral.mp4";v.original=v.image;v.media=List.of(v.image);v.memberKeys=List.of(v.key());v.identityKeys=List.of();v.groupMembers=List.of();v.groupingVersion=0;
        Post photo=Post.fromJson(fixtures.get(7).toJson());photo.id="9990002";photo.title="Neutral still fixture";photo.media=List.of(photo.image);photo.memberKeys=List.of(photo.key());photo.identityKeys=List.of();photo.groupMembers=List.of();
        Class<?> type=Class.forName("com.artcatalog.mobile.MainActivity$Gallery");Constructor<?> constructor=type.getDeclaredConstructors()[0];constructor.setAccessible(true);Object gallery=constructor.newInstance(activity,List.of(v,photo),null);
        method(activity,"openArtwork",Post.class,type).invoke(activity,v,gallery);method(activity,"fullscreenMediaReady",Post.class,int.class).invoke(activity,v,0);
        if("video-late".equals(activity.getIntent().getStringExtra("qaParityMode")))new Handler(Looper.getMainLooper()).postDelayed(()->{try{TextView status=(TextView)field(activity,"activeFullscreenStatus");FrameLayout frame=(FrameLayout)status.getParent();ZoomImageView image=null;for(int child=0;child<frame.getChildCount();child++)if(frame.getChildAt(child) instanceof ZoomImageView)image=(ZoomImageView)frame.getChildAt(child);Log.i(TAG,"VIDEO delayed kick attached="+frame.isAttachedToWindow());method(activity,"turnFullscreen",ZoomImageView.class,FrameLayout.class,int.class).invoke(activity,image,frame,0);}catch(Exception e){Log.e(TAG,"VIDEO delayed kick",e);}},400);
        Handler main=new Handler(Looper.getMainLooper());for(int index=1;index<=14;index++){int tick=index;main.postDelayed(()->{try{TextView status=(TextView)field(activity,"activeFullscreenStatus");Post current=(Post)field(activity,"activePost");if(status==null){server.close();return;}ViewGroup frame=(ViewGroup)status.getParent();VideoView video=frame.findViewWithTag("dart-viewer-video");Log.i(TAG,"VIDEO tick="+tick+" post="+current.id+" visible="+(video.getVisibility()==View.VISIBLE)+" playing="+video.isPlaying()+" position="+video.getCurrentPosition()+" bounds="+video.getWidth()+"x"+video.getHeight());}catch(Exception e){Log.e(TAG,"VIDEO status",e);}},index*1000L);}
    }
    private static void followingSlow(Activity activity,Store store)throws Exception{
        CatalogClient old=(CatalogClient)field(activity,"client");List<Post> fixtures=(List<Post>)field(old,"fixtures");old.close();if(!store.following("artcatalog_second_artist"))store.toggleFollow("artcatalog_second_artist");
        CatalogClient client=new CatalogClient((source,query,page,rating,sort)->{if(source.equals("sankaku"))Thread.sleep(6500);CatalogClient.Page result=new CatalogClient.Page();if(source.equals("danbooru"))for(Post p:fixtures)if(p.artistTag.equals(query)&&result.posts.size()<4)result.posts.add(p);result.fingerprints.put(source,query+":"+page);return result;});set(activity,"client",client);
        method(activity,"selectNav",int.class).invoke(activity,2);Handler main=new Handler(Looper.getMainLooper());long started=SystemClock.elapsedRealtime();
        main.postDelayed(()->{try{Object screen=((Object[])field(activity,"screens"))[2];List<Post> posts=(List<Post>)field(screen,"posts");Object adapter=field(screen,"adapter");int shown=((List<?>)field(adapter,"shown")).size();boolean loading=(boolean)field(screen,"loading");Log.i(TAG,"FOLLOWING HELD after="+(SystemClock.elapsedRealtime()-started)+" posts="+posts.size()+" shown="+shown+" loading="+loading);View card=find((View)field(screen,"view"),"Card");if(card==null)throw new IllegalStateException("No materialized card while peer held");card.performClick();Post active=(Post)field(activity,"activePost");Log.i(TAG,"FOLLOWING HELD clickOpened="+(active!=null)+" id="+(active==null?"":active.id));}catch(Exception e){Log.e(TAG,"FOLLOWING HELD failed",e);}},1600);
        main.postDelayed(()->{try{Post active=(Post)field(activity,"activePost");Object screen=((Object[])field(activity,"screens"))[2];Log.i(TAG,"FOLLOWING SETTLED activeDetail="+(active!=null)+" posts="+((List<?>)field(screen,"posts")).size()+" loading="+field(screen,"loading"));}catch(Exception e){Log.e(TAG,"FOLLOWING SETTLED failed",e);}},8500);
    }
    private static View find(View parent,String simpleName){if(parent.getClass().getSimpleName().equals(simpleName))return parent;if(parent instanceof ViewGroup)for(int i=0;i<((ViewGroup)parent).getChildCount();i++){View match=find(((ViewGroup)parent).getChildAt(i),simpleName);if(match!=null)return match;}return null;}
    private static void pagination(Activity activity,Store store)throws Exception{
        store.prefs.edit().putString("excludedTags","qa_hidden").putBoolean("hideViewedAndSaved",false).putBoolean("hideFollowedArtists",false).commit();method(activity,"runSearch",String.class).invoke(activity,"qa_hidden_pages");Handler main=new Handler(Looper.getMainLooper());
        for(int tick=1;tick<=5;tick++)main.postDelayed(()->{try{Object source=((Object[])field(activity,"screens"))[1];FeedListView list=(FeedListView)field(source,"list");BaseAdapter adapter=(BaseAdapter)field(source,"adapter");list.setSelectionFromTop(Math.max(0,adapter.getCount()-1),0);}catch(Exception error){Log.e(TAG,"PAGINATION scroll",error);}},tick*1200L);
        main.postDelayed(()->{try{Object source=((Object[])field(activity,"screens"))[1];List<Post> posts=(List<Post>)field(source,"posts");Set<String> keys=new HashSet<>();boolean unique=true,hidden=false;for(Post p:posts){for(String key:p.memberKeys)if(!keys.add(key))unique=false;hidden|=p.tags.contains("qa_hidden");}
            List<String> calls=(List<String>)field(field(activity,"client"),"pageCalls");List<String> scoped=new ArrayList<>();for(String call:calls)if(call.startsWith("qa_hidden_pages:"))scoped.add(call);
            Log.i(TAG,"PAGINATION posts="+posts.size()+" unique="+unique+" hidden="+hidden+" more="+field(source,"more")+" calls="+scoped);
        }catch(Exception error){Log.e(TAG,"PAGINATION result",error);}},7200);
    }
    private static void warmFollowed(Activity activity,Store store)throws Exception{
        CatalogClient original=(CatalogClient)field(activity,"client");List<Post> fixtures=(List<Post>)field(original,"fixtures");Post followed=fixtures.get(20);
        if(!store.following(followed.artistTag))store.toggleFollow(followed.artistTag);store.prefs.edit().putBoolean("hideFollowedArtists",true).putBoolean("hideViewedAndSaved",false).commit();
        Post fresh=Post.fromJson(fixtures.get(40).toJson());fresh.id="9992222";fresh.hash="eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee";fresh.artistTag="qa_unfollowed_warm";fresh.artistTags=List.of(fresh.artistTag);fresh.participants=new JSONArray().put(new JSONObject().put("tag",fresh.artistTag).put("role","artist"));fresh.memberKeys=List.of(fresh.key());fresh.identityKeys=List.of();fresh.groupMembers=List.of();fresh.image="";fresh.original="";fresh.media=List.of();fresh.imageRecords=new JSONArray();store.remember(List.of(followed,fresh));
        CatalogClient held=new CatalogClient((source,query,page,rating,sort)->{CatalogClient.Page result=new CatalogClient.Page();if(query.isBlank()){result.posts.add(followed);result.posts.add(fresh);result.fingerprints.put(source,"warm-neutral");}else Thread.sleep(4000);return result;});set(activity,"client",held);
        Object screen=((Object[])field(activity,"screens"))[0];Class<?> type=screen.getClass();method(activity,"load",type,boolean.class).invoke(activity,screen,true);Handler main=new Handler(Looper.getMainLooper());
        main.postDelayed(()->{try{List<Post> posts=(List<Post>)field(screen,"posts");boolean blocked=posts.stream().noneMatch(p->store.visible(List.of(p),false,true).isEmpty());boolean positive=posts.stream().anyMatch(p->p.key().equals(fresh.key()));
            method(activity,"fillRanking",type,List.class,String.class).invoke(activity,screen,List.of(followed,fresh),"QA warm ranking");method(activity,"loadRankings",type,int.class,String.class).invoke(activity,screen,field(screen,"generation"),"general");
            Log.i(TAG,"WARM FOLLOWED warmBlocked="+blocked+" unfollowedRetained="+positive+" warmCount="+posts.size());
        }catch(Exception error){Log.e(TAG,"WARM FOLLOWED warm",error);}},1000);
        main.postDelayed(()->{try{List<Post> ranked=new ArrayList<>();Object pending=field(screen,"pendingRanking");if(pending instanceof List)ranked.addAll((List<Post>)pending);ViewGroup ranking=(ViewGroup)field(screen,"ranking");for(int i=0;i<ranking.getChildCount();i++){View child=ranking.getChildAt(i);if(child.getClass().getSimpleName().equals("Card"))ranked.add((Post)field(child,"post"));}
            boolean absent=ranked.stream().noneMatch(p->store.visible(List.of(p),false,true).isEmpty());Log.i(TAG,"WARM FOLLOWED rankingBlocked="+absent+" ranked="+ranked.size());set(activity,"client",original);held.close();method(activity,"selectNav",int.class).invoke(activity,2);
        }catch(Exception error){Log.e(TAG,"WARM FOLLOWED rankings",error);}},2400);
        main.postDelayed(()->{try{Object followScreen=((Object[])field(activity,"screens"))[2];List<Post> posts=(List<Post>)field(followScreen,"posts");boolean available=posts.stream().anyMatch(p->store.visible(List.of(p),false,true).isEmpty());Log.i(TAG,"WARM FOLLOWED followingAvailable="+available+" count="+posts.size()+" enabled="+store.prefs.getBoolean("hideFollowedArtists",false));}catch(Exception error){Log.e(TAG,"WARM FOLLOWED following",error);}},4800);
    }
    private static void failedPreview(Activity activity,Store store,ImageLoader images)throws Exception{
        String file="https://s.sankakucomplex.com/o/ab/ab/abababababababababababababababab.jpg",expired=file+"?e=1&m=old",renewed=file+"?e=9999999999&m=fresh";
        android.graphics.Bitmap neutral=android.graphics.Bitmap.createBitmap(64,64,android.graphics.Bitmap.Config.ARGB_8888);neutral.eraseColor(0xff329cff);images.seed(renewed,neutral);neutral.recycle();
        ((Map<String,Long>)field(images,"failures")).put(ImageLoader.failureKey(expired,720),SystemClock.elapsedRealtime());java.util.concurrent.atomic.AtomicInteger refreshes=new java.util.concurrent.atomic.AtomicInteger();
        CatalogClient fake=new CatalogClient((source,query,page,rating,sort)->new CatalogClient.Page()){@Override void enrich(Post p)throws Exception{refreshes.incrementAndGet();Thread.sleep(250);p.preview=renewed;p.smallPreview=renewed;p.image=renewed;p.original=renewed;p.media=List.of(renewed);p.imageRecords=new JSONArray();}};set(activity,"client",fake);
        Post post=new Post();post.source="sankaku";post.id="qaRecovery1";post.title="Neutral renewed preview";post.rating="g";post.preview=expired;post.smallPreview=expired;post.image=expired;post.original=expired;post.media=List.of(expired);post.tags=List.of("landscape");
        Class<?> type=Class.forName("com.artcatalog.mobile.MainActivity$Screen");Constructor<?> constructor=type.getDeclaredConstructors()[0];constructor.setAccessible(true);Object screen=constructor.newInstance(activity,3);((Object[])field(activity,"screens"))[3]=screen;method(activity,"buildFeed",type).invoke(activity,screen);((List<Post>)field(screen,"posts")).add(post);set(screen,"loaded",true);set(screen,"more",false);
        method(activity,"display",View.class).invoke(activity,field(screen,"view"));((BaseAdapter)field(screen,"adapter")).notifyDataSetChanged();Handler main=new Handler(Looper.getMainLooper());for(int i=1;i<=5;i++)main.postDelayed(()->{try{method(activity,"prepareVisibleContent").invoke(activity);}catch(Exception e){Log.e(TAG,"PREVIEW recovery pulse",e);}},i*100L);
        main.postDelayed(()->{try{View card=find((View)field(screen,"view"),"Card");ImageView image=(ImageView)field(card,"image");Log.i(TAG,"FAILED PREVIEW renewed="+post.preview.equals(renewed)+" drawable="+(image.getDrawable() instanceof android.graphics.drawable.BitmapDrawable)+" refreshes="+refreshes.get()+" freshFailed="+images.failed(renewed,720));}catch(Exception e){Log.e(TAG,"FAILED PREVIEW result",e);}},1600);
    }
    private static void importFailure(Activity activity,Store store)throws Exception{method(activity,"profileTransferSettings").invoke(activity);Thread test=new Thread(()->{File blocked=new File(activity.getFilesDir(),"catalog-import-staged.json");boolean created=false;try{
        ((ExecutorService)field(store,"writes")).submit(()->{}).get();File catalog=new File(activity.getFilesDir(),"catalog.json");byte[] before;try(InputStream in=new FileInputStream(catalog)){before=in.readAllBytes();}JSONObject counters=ProfileTransfer.counts(ProfileTransfer.export(store.export()));String ai=store.prefs.getString("aiMode","all");
        if(blocked.exists())throw new IllegalStateException("Staging target already exists; leaving untouched");if(!blocked.mkdir())throw new IOException("Cannot create owned staging blocker");created=true;
        JSONObject document=new JSONObject("{format:'dart-profile',version:1,likes:[{key:'danbooru:9000888',source:'danbooru',id:'9000888',rating:'g',tags:['landscape'],images:[]}],bookmarks:[],history:[],follows:[],viewedIdentities:[],preferences:{aiMode:'generated-and-assisted'}}");boolean failed=false;try{store.importProfile(ProfileTransfer.parse(document.toString()),true);}catch(Exception expected){failed=true;}
        byte[] after;try(InputStream in=new FileInputStream(catalog)){after=in.readAllBytes();}JSONObject afterCounts=ProfileTransfer.counts(ProfileTransfer.export(store.export()));boolean unchanged=counters.toString().equals(afterCounts.toString()),settings=ai.equals(store.prefs.getString("aiMode","all"));Log.i(TAG,"IMPORT FAILURE failed="+failed+" diskUnchanged="+Arrays.equals(before,after)+" countersUnchanged="+unchanged+" settingsUnchanged="+settings);
    }catch(Exception error){Log.e(TAG,"IMPORT FAILURE check",error);}finally{if(created&&blocked.isDirectory()&&!blocked.delete())Log.e(TAG,"Could not remove owned empty staging directory");}},"DART-QA-import-failure");test.setDaemon(true);new Handler(Looper.getMainLooper()).postDelayed(test::start,2500);}
    private static void cacheRenewal(Activity activity,ImageLoader images) throws Exception {String path="https://s.sankakucomplex.com/o/01/23/0123456789abcdef0123456789abcdef.jpg",old=path+"?e=1&m=old",renewed=path+"?e=9&m=new";android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(32,32,android.graphics.Bitmap.Config.ARGB_8888);bitmap.eraseColor(0xff329cff);images.seed(old,bitmap);ImageView image=new ImageView(activity);images.bind(image,old,720,()->{android.graphics.drawable.Drawable before=image.getDrawable();images.bind(image,renewed,720);Log.i(TAG,"CACHE RENEWAL sameDrawable="+(before==image.getDrawable())+" prepared="+images.prepared(renewed,720)+" bitmap="+(image.getDrawable() instanceof android.graphics.drawable.BitmapDrawable));images.release(image);});bitmap.recycle();}
    private static boolean has(JSONArray values,String key){if(values!=null)for(int i=0;i<values.length();i++){JSONObject value=values.optJSONObject(i);if(value!=null&&(value.optString("key").equals(key)||value.optJSONArray("memberKeys")!=null&&value.optJSONArray("memberKeys").toString().contains('"'+key+'"')))return true;}return false;}
    private static Object field(Object target,String name)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}
    private static void set(Object target,String name,Object value)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);f.set(target,value);}
    private static Method method(Object target,String name,Class<?>...params)throws Exception{Method m=target.getClass().getDeclaredMethod(name,params);m.setAccessible(true);return m;}
}
